    t.rect(7, 3, 2, 2, [54, 30, 26]);
    t.set(7, 2, [226, 76, 66]);
    return t;
  },
  dandelion(r) {
    const t = new Tex();
    t.fill([0, 0, 0, 0]);
    t.rect(7, 6, 2, 10, [58, 124, 46]);
    t.rect(5, 11, 2, 1, [70, 142, 52]);
    t.rect(9, 12, 2, 1, [70, 142, 52]);
    t.rect(6, 2, 4, 4, [236, 200, 52]);
