.iconBtn:hover { background: rgba(40, 34, 24, 0.8); transform: translateY(-1px); }

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 26px;
  height: 26px;
  transform: translate(-50%, -50%);
