#crosshair .ch.h { left: 2px; right: 2px; top: 12px; height: 2px; }
#crosshair .ch.v { top: 2px; bottom: 2px; left: 12px; width: 2px; }
#ring {
  position: absolute;
  inset: -9px;
  border-radius: 50%;
  opacity: 0;
  transition: opacity 0.1s;
  background: conic-gradient(#ffe9a8 0deg, #ffe9a8 0deg, transparent 0deg);
  -webkit-mask: radial-gradient(closest-side, transparent 63%, #000 65%, #000 82%, transparent 84%);
  mask: radial-gradient(closest-side, transparent 63%, #000 65%, #000 82%, transparent 84%);
  filter: drop-shadow(0 0 4px rgba(0, 0, 0, 0.6));
}
