#hoverName {
  position: absolute;
  left: 50%;
  top: calc(50% + 30px);
  transform: translateX(-50%);
  font-size: 12px;
  color: #fdf6e6;
  text-shadow: 0 1px 3px #000;
  opacity: 0;
  transition: opacity 0.2s;
  white-space: nowrap;
  letter-spacing: 0.06em;
}
