import { BLOCKS } from './blocks.js';
import { makeIcon } from './textures.js';

export const $ = (sel, root = document) => root.querySelector(sel);

export function buildHotbar(el, hotbar, selected, onPick) {
  el.textContent = '';
  hotbar.forEach((id, i) => {
    const slot = document.createElement('button');
    slot.className = 'slot' + (i === selected ? ' selected' : '');
    slot.dataset.slot = String(i);
    slot.title = `${BLOCKS[id].name} (${i + 1})`;
    slot.setAttribute('aria-label', `${i + 1}: ${BLOCKS[id].name}`);
    const ic = document.createElement('span');
    ic.className = 'ic';
    ic.appendChild(makeIcon(BLOCKS[id], 52));
    const num = document.createElement('span');
    num.className = 'num';
    num.textContent = String(i + 1);
    slot.append(ic, num);
    slot.addEventListener('pointerdown', (e) => e.stopPropagation());
    slot.addEventListener('click', (e) => { e.stopPropagation(); onPick(i); });
    el.appendChild(slot);
  });
}

export function updateHotbarSelection(el, selected) {
  [...el.children].forEach((s, i) => s.classList.toggle('selected', i === selected));
}

export function buildPalette(el, activeId, onPick) {
  el.textContent = '';
  const list = BLOCKS.filter((b) => b && b.placeable);
  for (const def of list) {
    const btn = document.createElement('button');
    btn.className = 'paletteItem' + (def.id === activeId ? ' active' : '');
    btn.type = 'button';
    btn.appendChild(makeIcon(def, 44));
    const label = document.createElement('span');
    label.className = 'pname';
    label.textContent = def.name;
    btn.appendChild(label);
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      onPick(def.id);
    });
    el.appendChild(btn);
  }
}

let toastTimer = 0;
export function toast(msg, ms = 1600) {
  const el = $('#toast');
  if (!el) return;
  el.textContent = msg;
  el.classList.add('on');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('on'), ms);
}

export function setBreakRing(el, progress) {
  const cross = $('#crosshair');
  if (!cross) return;
  if (progress == null || progress <= 0.001) {
    cross.classList.remove('mining');
    el.style.background = '';
    return;
  }
  cross.classList.add('mining');
  const deg = Math.min(1, progress) * 360;
  el.style.background = `conic-gradient(#ffe9a8 0deg, #ffe9a8 ${deg}deg, rgba(255,255,255,0.12) ${deg}deg)`;
}

export function fadeOut(el, ms = 250) {
  if (!el) return;
  el.classList.remove('show');
  setTimeout(() => el.classList.add('hidden'), ms);
}
export function show(el) { if (el) { el.classList.remove('hidden'); requestAnimationFrame(() => el.classList.add('show')); } }
export function hide(el) { if (el) { el.classList.remove('show'); } }

import * as THREE from '../vendor/three.module.js';
import { buildAtlas, TILE_NAMES, TILES } from './textures.js';
import {
  BLOCKS, B, PLACEABLE, DEFAULT_HOTBAR, blockGeometry, createMaterials,
} from './blocks.js';
import { World, ChunkView, CH, HEIGHT, SEA } from './world.js';
import { Player, raycastVoxel } from './player.js';
import { Sky } from './sky.js';
import { Sound } from './audio.js';
import {
  $, buildHotbar, updateHotbarSelection, buildPalette, toast, setBreakRing,
} from './ui.js';

/* ------------------------------------------------------------------ *
 *  Setup
 * ------------------------------------------------------------------ */

const SAVE_KEY = 'minecraft3d.save.v1';
const isTouch = window.matchMedia('(pointer: coarse)').matches ||
  (('ontouchstart' in window) && navigator.maxTouchPoints > 0);
if (isTouch) document.body.classList.add('touch');

function loadSave() {
  try { return JSON.parse(localStorage.getItem(SAVE_KEY) || 'null'); } catch { return null; }
}
const save = loadSave();
const params = new URLSearchParams(location.search);
const seedParam = Number(params.get('seed'));
const seed = Number.isFinite(seedParam) && seedParam !== 0 ? seedParam : (save?.seed || 1337);

const canvas = $('#game');
let renderer;
try {
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
} catch (err) {
  $('#loadText').textContent = 'WebGL is unavailable in this browser.';
  throw err;
}
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.setClearColor(0x87ceeb, 1);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xcfe8f5, 58, 108);
const camera = new THREE.PerspectiveCamera(74, window.innerWidth / window.innerHeight, 0.08, 900);
camera.rotation.order = 'YXZ';
scene.add(camera);

const atlas = buildAtlas();
const materials = createMaterials(atlas.texture);
const sky = new Sky(scene, renderer);
const world = new World(seed, save?.edits);
const view = new ChunkView(scene, world, materials, isTouch ? 5 : 6);
const player = new Player(world);
const sound = new Sound();
if (save?.muted) sound.setMuted(true);

/* ------------------------------------------------------------------ *
 *  Restore or find the spawn point
 * ------------------------------------------------------------------ */

const startX = Math.round(save?.player?.x ?? 8);
const startZ = Math.round(save?.player?.z ?? 8);
for (let dz = -1; dz <= 1; dz++) {
  for (let dx = -1; dx <= 1; dx++) world.getChunk((startX >> 4) + dx, (startZ >> 4) + dz);
}
let restored = false;
if (save?.player && Number.isFinite(save.player.x)) {
  const p = save.player;
  const below = world.getBlock(Math.floor(p.x), Math.floor(p.y - 0.3), Math.floor(p.z));
  const head = world.getBlock(Math.floor(p.x), Math.floor(p.y + 1.2), Math.floor(p.z));
  if (below !== 0 && head !== B.WATER) {
    player.pos.set(p.x, p.y, p.z);
    player.yaw = Number(p.yaw) || 0;
    player.pitch = Number(p.pitch) || 0;
    restored = true;
  }
}
if (!restored) {
  player.spawnAt(startX, startZ);
  player.yaw = -0.55;
  player.pitch = -0.06;
}

/* ------------------------------------------------------------------ *
 *  Hotbar + palette
 * ------------------------------------------------------------------ */

const defaultHotbar = [...DEFAULT_HOTBAR];
let hotbar = Array.isArray(save?.hotbar) && save.hotbar.length === 9
  ? save.hotbar.map((id) => (BLOCKS[id] && BLOCKS[id].placeable ? id : B.DIRT))
  : defaultHotbar;
let slot = Math.min(8, Math.max(0, Number(save?.slot) || 0));
const hotbarEl = $('#hotbar');
const itemNameEl = $('#itemName');
let itemNameTimer = 0;

function item() { return hotbar[slot]; }
function refreshHotbar() {
  buildHotbar(hotbarEl, hotbar, slot, (i) => selectSlot(i));
  updateHotbarSelection(hotbarEl, slot);
}
function flashItemName(ms = 1700) {
  itemNameEl.textContent = BLOCKS[item()].name;
  itemNameEl.classList.add('show');
  clearTimeout(itemNameTimer);
  itemNameTimer = setTimeout(() => itemNameEl.classList.remove('show'), ms);
}
function selectSlot(i) {
  slot = ((i % 9) + 9) % 9;
  updateHotbarSelection(hotbarEl, slot);
  flashItemName();
  sound.click();
  updateHeldItem();
