```js
function pickScenicSpawn() {
  let best = null;
  const cx = startX, cz = startZ;
  for (let r = 0; r <= 48; r += 6) {
    const steps = r === 0 ? 1 : 8;
    for (let i = 0; i < steps; i++) {
      const a = (i / steps) * Math.PI * 2 + 0.3;
      const x = Math.round(cx + Math.cos(a) * r);
      const z = Math.round(cz + Math.sin(a) * r);
      const h = world.surfaceY(x, z);
      if (h <= SEA + 1 || h > 66) continue;
      const surf = world.getBlock(x, h, z);
      if (surf === B.WATER) continue;
      let sum = 0, lowDir = {x:0,z:0}, low = 999;
      const dirs = 8;
      for (let d = 0; d < dirs; d++) {
        const ang = (d / dirs) * Math.PI * 2;
        const dx = Math.cos(ang), dz = Math.sin(ang);
        let sh = 0;
        for (let k = 1; k <= 3; k++) {
          const sx = Math.round(x + dx * k * 12), sz = Math.round(z + dz * k * 12);
          sh += world.surfaceY(sx, sz);
        }
        sh /= 3;
        sum += sh;
        if (sh < low) { low = sh; lowDir = {x: dx, z: dz}; }
      }
      const avg = sum / dirs;
      // prevent being right beside a tree
      let tree = 0;
      for (let ox = -2; ox <= 2; ox++) for (let oz = -2; oz <= 2; oz++) {
        if (world.getBlock(x+ox, h+2, z+oz) === B.LEAVES) tree++;
      }
      const score = h * 0.8 + Math.max(0, h - avg) * 2.2 + (low < SEA ? 6 : 0) - tree * 3 + r * 0.02;
      if (!best || score > best.score) best = { x, z, h, yaw: Math.atan2(-lowDir.x, -lowDir.z), score };
    }
  }
  return best;
}
```
